import{_ as t,o as n,c as a,a0 as o}from"./chunks/framework.ysVzM4be.js";const p=JSON.parse('{"title":"ADR 0007: Consultations are independent from Tickets","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0007-consultations-are-independent-from-tickets.md","filePath":"adr/0007-consultations-are-independent-from-tickets.md"}'),s={name:"adr/0007-consultations-are-independent-from-tickets.md"};function r(i,e,d,c,l,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0007-consultations-are-independent-from-tickets" tabindex="-1">ADR 0007: Consultations are independent from Tickets <a class="header-anchor" href="#adr-0007-consultations-are-independent-from-tickets" aria-label="Permalink to &quot;ADR 0007: Consultations are independent from Tickets&quot;">​</a></h1><p>Status: accepted Date: 2026-09-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The operator needs to start interactive Agent work from free text, such as a <code>grill-with-docs</code> discussion. This work has no external Ticket and can require several rounds of operator input. A synthetic Ticket would invent source facts and a Work cycle, while attachment to the selected Ticket would make unrelated work affect that Ticket&#39;s lifecycle.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>A Consultation is durable, first-class work that is independent of Tickets. It has its own type, state, history, attention, and recovery behavior, while it shares Agent types, Environments, Repository resolution, and herdr polling (ADR 0006) with Handoffs.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Consultations use a separate TUI view and durable state instead of appearing in the Ticket list. Starting or closing one never changes Ticket state, and manual Consultations do not consume the auto-handoff Parallel limit. Pane output is read from Herdr and is not continuously persisted; only settled and best-effort close snapshots are stored. Keystrokes sent in Agent interaction mode are not recorded as a transcript.</p>',8)])])}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
